display.text:
#!/usr/bin/env bash
set -Eeuo pipefail
IFS=$'\n\t'

upper() {
  printf '%s\n' "${1^^}"
}

input.newString:
upper() {
  printf '%s\n' "${1^^}"
}

reverse() {
  local input=$1 output='' i
  for (( i = ${#input} - 1; i >= 0; i-- )); do
    output+=${input:i:1}
  done
  printf '%s\n' "$output"
}

